import {
  Group,
  PlaneGeometry,
  MeshBasicNodeMaterial,
  Mesh,
  Vector2,
} from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new Group();
  group.name = 'cta-label';

  // --- Background plane ---
  const bgGeom = new PlaneGeometry(1, 0.625); // width / height from aspect? We'll size based on text later, but default 512x320 ratio
  const bgMat = new MeshBasicNodeMaterial({
    color: config.visual.colors.surface, // fallback
    transparent: false,
  });

  const bgMesh = new Mesh(bgGeom, bgMat);
  bgMesh.name = 'cta-bg';

  // Load the brushed metal texture
  const texture = ctx.textureLoader.load(config.assets.imageUrl);
  texture.wrapS = texture.wrapT = 1000; // RepeatWrapping
  texture.repeat.set(1, 1);
  bgMat.map = texture;

  // Size the background plane to match the texture aspect ratio (512x320 ≈ 1.6)
  const aspect = 512 / 320; // ~1.6
  const width = aspect * 0.625; // height 0.625 => width 1.0
  bgGeom.scale(width, 0.625, 1); // adjust geometry scale directly

  group.add(bgMesh);

  // --- Text overlay ---
  const textContent = config.textContent[0]; // assuming single text block
  const fontSizePx = textContent.size || 42; // from spec "42px 400"
  const fontWeight = textContent.weight || 400;
  const fontFamily = 'Lora'; // display font

  const textMesh = ctx.fontAtlas.createText({
    text: textContent.text,
    fontFamily,
    fontWeight,
    fontSize: fontSizePx,
    color: config.visual.colors.accent, // CTA accent color #ff2a38
    letterSpacing: 0.02,
    align: 'center',
    anchor: { x: 0.5, y: 0.5 },
    // Optional: use preloaded font atlas from ctx.fontAtlas
  });

  textMesh.name = 'cta-text';
  textMesh.position.set(0, 0, 0.01); // slight z-offset to avoid z-fighting
  group.add(textMesh);

  // --- Apply scene placement ---
  const pos = config.scenePosition;
  group.position.copy(pos.position || new Vector2(0, -2.85));
  group.position.z = pos.z !== undefined ? pos.z : 0.26;
  group.rotation.set(
    pos.rotation?.x || 0,
    pos.rotation?.y || 0,
    pos.rotation?.z || 0,
  );
  group.scale.set(
    pos.scale?.x || 1,
    pos.scale?.y || 1,
    pos.scale?.z || 1,
  );

  // --- Event handlers (none) ---
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    bgGeom.dispose();
    bgMat.dispose();
    texture.dispose();
    // font atlas text mesh cleanup handled by ctx.fontAtlas? We assume it provides dispose on the mesh.
    if (textMesh.dispose) textMesh.dispose(); // if it has dispose method; otherwise we rely on GC.
  };

  return group;
}
